"""
RAG_eval.py
Automatically collect evaluation data from files and evaluate your RAG pipeline using Ragas.
"""

import os
import json
import pandas as pd
from ragas import evaluate
from ragas.metrics import faithfulness, answer_relevancy, context_precision, context_recall

# Example: Load evaluation data from a JSON file generated by your app
# The file should contain a list of dicts with keys: question, generated_answer, ground_truth, contexts
EVAL_DATA_PATH = "rag_eval_data.json"  # Change this to your actual data file

def load_eval_data(path):
    if not os.path.exists(path):
        print(f"Evaluation data file not found: {path}")
        return []
    with open(path, "r", encoding="utf-8") as f:
        return json.load(f)

data = load_eval_data(EVAL_DATA_PATH)

if not data:
    print("No evaluation data found. Please generate rag_eval_data.json from your RAG pipeline.")
else:
    df = pd.DataFrame(data)
    results = evaluate(
        df,
        metrics=[faithfulness, answer_relevancy, context_precision, context_recall]
    )
    print("RAG Evaluation Results:")
    print(results)